def _load_usage_cache():
    if _USAGE_CACHE_FILE.exists():
        try:
            cached = json.loads(_USAGE_CACHE_FILE.read_text())
            _usage_cache["data"] = cached.get("data")
            _usage_cache["ts"] = cached.get("ts", 0.0)
